def longest_palindrome(s: str) -> int:
    """Length of the longest palindromic substring, expanding around every centre."""
    n: int = len(s)
    best: int = 0
    for centre in range(2 * n - 1):
        lo: int = centre // 2
        hi: int = lo + centre % 2
        while lo >= 0 and hi < n and s[lo] == s[hi]:
            lo -= 1
            hi += 1
        if hi - lo - 1 > best:
            best = hi - lo - 1
    return best

